/* === js/errlog.js === */
/* ============================================================
   errlog.js — Error Log (v1.2.92). Loaded FIRST.

   Keeps the last 50 errors of the launcher (script errors and
   promises nobody caught) with the time, the file and the line, so
   a problem can be read in Settings > Performance > Error Log
   instead of being guessed. The same error twice in a row is
   counted, not repeated. Saved at most every 2 s (one small JSON).
   The bridge keeps its own list (bridge/service.js, /bridge-info).
   ============================================================ */
(function (global) {
    "use strict";

    var KEY = "apl.errlog", MAX = 50, buf = [], dirty = false, timer = null;
    try {
        buf = JSON.parse(global.localStorage.getItem(KEY) || "[]");
        if (!Array.isArray(buf)) buf = [];
    } catch (e) { buf = []; }

    function flush() {
        timer = null;
        if (!dirty) return;
        dirty = false;
        try { global.localStorage.setItem(KEY, JSON.stringify(buf)); } catch (e) {}
    }

    function push(kind, msg, where) {
        try {
            var m = String(msg || "").replace(/\s+/g, " ").slice(0, 160);
            var last = buf[buf.length - 1];
            if (last && last.m === m && last.k === kind) { last.n = (last.n || 1) + 1; last.t = Date.now(); }
            else {
                buf.push({ t: Date.now(), k: kind, m: m, w: String(where || "").slice(0, 80), n: 1 });
                if (buf.length > MAX) buf.splice(0, buf.length - MAX);
            }
            dirty = true;
            if (!timer) timer = setTimeout(flush, 2000);
        } catch (e) {}
    }

    // Not in the capture phase: a missing picture is not a script error and does not come here.
    global.addEventListener("error", function (ev) {
        var f = ev && ev.filename ? String(ev.filename).replace(/^.*\//, "") + ":" + (ev.lineno || 0) : "";
        push("error", (ev && ev.message) || "error", f);
    }, false);
    global.addEventListener("unhandledrejection", function (ev) {
        var r = ev && ev.reason;
        push("promise", (r && (r.message || r)) || "rejected", "");
    }, false);

    global.APL_ERRLOG = {
        list: function () { return buf.slice(); },
        clear: function () { buf = []; dirty = false; try { global.localStorage.removeItem(KEY); } catch (e) {} },
        push: push
    };
})(window);

/* === js/safe-store.js === */
/* ============================================================
   safe-store.js — a full browser storage no longer loses a save silently (v1.2.102). Loaded right after errlog.js.

   Before: every `localStorage.setItem` in the launcher sat in its own try/catch, so when the storage was
   full the write simply failed and nothing told anyone (a task or a setting could be lost without a trace).

   Now: ONLY when a write fails because the storage is full, this layer
     1. frees space by removing two things that are rebuilt by themselves — the Error Log copy
        ("apl.errlog") and the last weather snapshot ("apl.weather.last", fetched again at the next refresh),
        one at a time, trying the write again after each;
     2. if the write still does not fit, throws the SAME error as before, so every caller behaves exactly
        as it did (their own try/catch);
     3. in both cases the Error Log gets one line ("storage full ..."), so it can be read in Settings.
   Nothing else is touched: no user data (tasks, settings, backups, profiles, icons, prayer data) is ever
   removed, and a write that succeeds goes through unchanged.
   ============================================================ */
(function (global) {
    "use strict";
    if (global.__aplSafeStore) return;
    var proto = null, orig = null;
    try { proto = global.Storage && global.Storage.prototype; orig = proto && proto.setItem; } catch (e0) {}
    if (!proto || typeof orig !== "function") return;

    var DISPOSABLE = ["apl.errlog", "apl.weather.last"];

    function isQuota(e) {
        if (!e) return false;
        return e.name === "QuotaExceededError" || e.name === "NS_ERROR_DOM_QUOTA_REACHED" ||
               e.code === 22 || e.code === 1014 || /quota/i.test(String(e.message || ""));
    }
    function note(msg, key) {
        try { if (global.APL_ERRLOG && global.APL_ERRLOG.push) global.APL_ERRLOG.push("storage", msg, String(key || "").slice(0, 60)); } catch (e) {}
    }

    var patched = function (key, value) {
        try {
            return orig.call(this, key, value);
        } catch (e) {
            if (!isQuota(e) || this !== global.localStorage) throw e;
            if (String(key) === "apl.errlog") throw e;               // the log itself is disposable; never log about it (no loop)
            var self = this, freed = [];
            for (var i = 0; i < DISPOSABLE.length; i++) {
                var dk = DISPOSABLE[i];
                if (dk === String(key)) continue;                    // never delete the very key being written
                try { if (self.getItem(dk) === null) continue; self.removeItem(dk); freed.push(dk); } catch (e1) { continue; }
                try {
                    orig.call(self, key, value);
                    note("storage full: saved after freeing " + freed.join(", "), key);
                    return;
                } catch (e2) { if (!isQuota(e2)) throw e2; }
            }
            note("storage full: could not save", key);
            throw e;                                                  // same error as before for the caller
        }
    };
    try {
        proto.setItem = patched;
        global.__aplSafeStore = true;
    } catch (e3) {}
})(window);

/* === js/timers.js === */
/* ============================================================
   timers.js — ONE shared timer for the launcher's periodic jobs (v1.2.100). Loaded second, after errlog.js.

   Before, about ten separate setInterval timers ran for ever (clock, theme, night dimming, Control Center,
   screen saver, weather, wallpapers, task and prayer ticks...). Now each of them registers here, and ONE
   setTimeout is armed for the nearest job. Jobs that fall due within 1 s of each other run in the same wake-up.

     APL.timers.every(name, ms, fn [, { hidden: true }])   register (or replace) a job; the first run is after ms
     APL.timers.cancel(name)                               stop it
     APL.timers.info()                                     [{ name, ms, inMs, hidden }] for diagnosis

   While the launcher is not in front (document.hidden) the jobs are skipped, exactly as the old
   "if (document.hidden) return" lines did, unless the job asks for { hidden: true }.
   An error in one job is thrown again on its own, so the Error Log sees it, and the other jobs still run.
   Not here, on purpose: the radio's own timers, Vetro watch (its period changes), the pages' own tick while
   they are open, the background daemon and the bridge service.
   ============================================================ */
(function (global) {
    "use strict";
    var APL = global.APL = global.APL || {};
    var jobs = {}, timer = 0, WINDOW = 1000, MIN = 250;

    function hidden() { try { return !!global.document.hidden; } catch (e) { return false; } }
    function names() { return Object.keys(jobs); }

    function arm() {
        if (timer) { global.clearTimeout(timer); timer = 0; }
        var best = Infinity, h = hidden(), i, j, ks = names();
        for (i = 0; i < ks.length; i++) {
            j = jobs[ks[i]];
            if (h && !j.hidden) continue;
            if (j.next < best) best = j.next;
        }
        if (best === Infinity) return;
        timer = global.setTimeout(fire, Math.max(MIN, best - Date.now()));
    }

    function fire() {
        timer = 0;
        var now = Date.now(), h = hidden(), due = [], ks = names(), i, j;
        for (i = 0; i < ks.length; i++) {
            j = jobs[ks[i]];
            if (h && !j.hidden) continue;
            if (j.next - now <= WINDOW) due.push(j);
        }
        for (i = 0; i < due.length; i++) {
            j = due[i];
            if (jobs[j.name] !== j) continue;          // cancelled or replaced by an earlier job of this round
            j.next = Date.now() + j.ms;
            try { j.fn(); } catch (e) { (function (err) { global.setTimeout(function () { throw err; }, 0); })(e); }
        }
        arm();
    }

    function every(name, ms, fn, opts) {
        ms = Math.max(1000, parseInt(ms, 10) || 0);
        if (typeof fn !== "function") return;
        jobs[name] = { name: name, ms: ms, fn: fn, hidden: !!(opts && opts.hidden), next: Date.now() + ms };
        arm();
    }
    function cancel(name) {
        if (jobs[name]) { delete jobs[name]; arm(); }
    }

    /* coming back to the front: the jobs that were skipped wait a full period again (the code that needs an
       immediate refresh on return does it itself, with its own visibilitychange line) */
    try {
        global.document.addEventListener("visibilitychange", function () {
            if (!hidden()) {
                var ks = names(), now = Date.now();
                for (var i = 0; i < ks.length; i++) if (!jobs[ks[i]].hidden) jobs[ks[i]].next = now + jobs[ks[i]].ms;
            }
            arm();
        });
    } catch (e) {}

    /* v1.2.115: run one job now (its next run is a full period from now). The launcher uses it when it comes back
       to the front (APL.refreshHome): the prayer card and the task card show the right time at once instead of
       waiting for their next tick. Only the jobs named by the caller; the others keep waiting as before. */
    function runNow(name) {
        var j = jobs[name];
        if (!j) return false;
        j.next = Date.now() + j.ms;
        try { j.fn(); } catch (e) { (function (err) { global.setTimeout(function () { throw err; }, 0); })(e); }
        arm();
        return true;
    }

    /* v1.2.115: a JSON request that can never hang. The answer (headers AND body) must arrive within `ms`,
       otherwise the promise is rejected (and the request aborted where the browser can) so the callers' own
       error paths run: before, a stalled request left the weather "busy" for ever. */
    function fetchJSON(url, ms, opts) {
        return new Promise(function (resolve, reject) {
            var done = false, ctl = null, o = opts || {};
            try { ctl = global.AbortController ? new global.AbortController() : null; } catch (e) { ctl = null; }
            if (ctl) o.signal = ctl.signal;
            var to = global.setTimeout(function () {
                if (done) return;
                done = true;
                try { if (ctl) ctl.abort(); } catch (e) {}
                reject(new Error("timeout after " + Math.round(ms / 1000) + " s"));
            }, ms);
            function fail(e) { if (done) return; done = true; global.clearTimeout(to); reject(e); }
            global.fetch(url, o).then(function (r) {
                if (!r.ok) throw new Error("HTTP " + r.status);
                return r.json();
            }).then(function (j) {
                if (done) return;
                done = true; global.clearTimeout(to); resolve(j);
            }, fail);
        });
    }
    APL.fetchJSON = fetchJSON;

    APL.timers = {
        every: every,
        cancel: cancel,
        runNow: runNow,
        info: function () {
            var now = Date.now();
            return names().map(function (k) { return { name: k, ms: jobs[k].ms, inMs: jobs[k].next - now, hidden: jobs[k].hidden }; });
        }
    };
})(window);

/* === js/lifecycle.js === */
/* ============================================================
   Salah Launcher — Lifecycle Management (APL.lifecycle)
   Centralized scope, timer suspension, audio teardown, and cache trimmer.
   ES2019 / Chromium 76 compatible.
   ============================================================ */
(function (global) {
    "use strict";

    var APL = global.APL = global.APL || {};
    var scopes = {}, byNav = [], trimmers = [], suspended = false;

    function Scope(name) {
        this.name = name;
        this.items = [];
        this.timers = [];
        this.audios = [];
        this.dead = false;
    }

    Scope.prototype.on = function (target, type, fn, opts) {
        if (this.dead || !target) return fn;
        target.addEventListener(type, fn, opts);
        this.items.push(function () {
            try { target.removeEventListener(type, fn, opts); } catch (e) {}
        });
        return fn;
    };

    Scope.prototype.timeout = function (fn, ms, keep) {
        var t = { fn: fn, ms: ms, due: Date.now() + ms, keep: !!keep, id: 0, once: true };
        this._arm(t);
        this.timers.push(t);
        return t;
    };

    Scope.prototype.interval = function (fn, ms, keep) {
        var t = { fn: fn, ms: ms, keep: !!keep, id: 0, once: false };
        this._arm(t);
        this.timers.push(t);
        return t;
    };

    Scope.prototype._arm = function (t) {
        var self = this, ms = t.once ? Math.max(0, t.due - Date.now()) : t.ms;
        t.id = (t.once ? setTimeout : setInterval)(function () {
            if (t.once) self.clear(t);
            try {
                t.fn();
            } catch (e) {
                setTimeout(function () { throw e; }, 0);
            }
        }, ms);
    };

    Scope.prototype.clear = function (t) {
        if (!t) return;
        clearTimeout(t.id);
        clearInterval(t.id);
        t.id = 0;
        var i = this.timers.indexOf(t);
        if (i >= 0) this.timers.splice(i, 1);
    };

    Scope.prototype.audio = function (el) {
        if (el && this.audios.indexOf(el) < 0) this.audios.push(el);
        return el;
    };

    Scope.prototype.own = function (disposeFn) {
        if (typeof disposeFn === "function") this.items.push(disposeFn);
    };

    Scope.prototype.suspend = function () {
        this.timers.slice().forEach(function (t) {
            if (t.keep || !t.id) return;
            clearTimeout(t.id);
            clearInterval(t.id);
            t.id = 0;
            if (t.once) t.remain = Math.max(0, t.due - Date.now());
        });
    };

    Scope.prototype.resume = function () {
        var self = this;
        this.timers.slice().forEach(function (t) {
            if (t.keep || t.id) return;
            if (t.once) t.due = Date.now() + (t.remain || 0);
            self._arm(t);
        });
    };

    Scope.prototype.dispose = function () {
        if (this.dead) return;
        this.dead = true;
        this.timers.slice().forEach(function (t) {
            clearTimeout(t.id);
            clearInterval(t.id);
        });
        this.items.forEach(function (f) {
            try { f(); } catch (e) {}
        });
        this.audios.forEach(function (a) {
            try {
                a.pause();
                a.removeAttribute("src");
                a.load();
            } catch (e) {}
        });
        this.timers = [];
        this.items = [];
        this.audios = [];
        delete scopes[this.name];
    };

    APL.lifecycle = {
        scope: function (name) {
            return scopes[name] || (scopes[name] = new Scope(name));
        },
        scopeFor: function (nav, name) {
            var s = this.scope(name);
            byNav.push({ nav: nav, name: name });
            return s;
        },
        navClosed: function (nav) {
            for (var i = byNav.length - 1; i >= 0; i--) {
                if (byNav[i].nav === nav) {
                    var n = byNav[i].name;
                    byNav.splice(i, 1);
                    if (scopes[n]) scopes[n].dispose();
                }
            }
            APL.lifecycle.trim("page-closed");
        },
        onTrim: function (fn) {
            if (typeof fn === "function") trimmers.push(fn);
        },
        trim: function (why) {
            trimmers.forEach(function (f) {
                try { f(why); } catch (e) {}
            });
        },
        stats: function () {
            var o = { scopes: 0, listeners: 0, timers: 0, audios: 0 };
            Object.keys(scopes).forEach(function (k) {
                var s = scopes[k];
                o.scopes++;
                o.listeners += s.items.length;
                o.timers += s.timers.length;
                o.audios += s.audios.length;
            });
            return o;
        }
    };

    if (global.document) {
        global.document.addEventListener("visibilitychange", function () {
            var hid = global.document.hidden;
            if (hid === suspended) return;
            suspended = hid;
            Object.keys(scopes).forEach(function (k) {
                scopes[k][hid ? "suspend" : "resume"]();
            });
            if (hid) APL.lifecycle.trim("suspend");
        });
    }

})(window);

/* === js/site-config.js === */
/* ============================================================
   site-config.js — this build's own defaults (Salah Launcher — Egypt).

   Everything the custom build adds reads its defaults from here:
   the prayer times city, the weather place, the radio station.
   Nothing personal is hidden anywhere else, so one file can be
   swapped for the public copy (tools/make-public.sh turns this file
   into the Cairo defaults).

   CUSTOM  : this package is a custom build. It is never updated from
             the original project on GitHub (boot.js / updater.js).
   ============================================================ */
(function (global) {
    "use strict";

    global.APL_SITE = {
        custom: true,                 // custom build: no automatic updates from the original repo
        buildName: "Salah Launcher",

        /* Prayer times: AlAdhan API, Egyptian General Authority of Survey (method 5),
           Asr at the usual time (school 0), Africa/Cairo. */
        prayer: {
            method: 5,                // Egyptian General Authority of Survey
            school: 0,                // Shafi'i (the usual Asr)
            timezone: "Africa/Cairo",
            city: "cairo",            // key in cities.js
            alerts: true,             // spoken short alert at prayer time
            pauseRadio: true,         // pause the radio while the alert plays, then resume
            days: 45                 // cache this many days of times locally
        },

        /* Weather: Open-Meteo, no key, no device location. */
        weather: {
            place: "cairo",           // key in cities.js (lat/lon in cities.js)
            units: "metric",
            refreshMinutes: 15
        },

        /* Radio: Egyptian Qur'an Radio (Cairo), over the internet. AVPlay needs a DIRECT
           MP3 stream, not a web page, so these are stream addresses, tried in this order
           (the one that worked last is tried first). Add more at the end if needed. */
        radio: {
            urls: [
                "https://stream.radiojar.com/8s5u5tpdtwzuv",
                "https://n12.radiojar.com/8s5u5tpdtwzuv",
                "http://n12.radiojar.com/8s5u5tpdtwzuv",
                "http://stream.radiojar.com/8s5u5tpdtwzuv"
            ],
            name: "إذاعة القرآن الكريم من القاهرة",
            background: false         // the radio plays only while Salah Launcher is in front
        },

        /* Home wallpapers: the 20 compact local wallpapers, one every five minutes. */
        wallpapers: {
            every: 5,                 // minutes
            on: true
        },

        /* Support: the page shown as a QR code in Settings > Support.
           Put your own donation / support link here (Ko-fi, PayPal.Me, Buy Me a Coffee ...).
           Up to 216 characters. Empty = the Support item only says the link is not set. */
        support: {
            url: "https://ko-fi.com/abdulrahmankhalid32781"
        }
    };
})(window);

/* === js/diag.js === */
/* ============================================================
   diag.js — a start-up that doesn't finish is said on screen.

   Loaded first. It notes the script errors, and if the Home Screen
   hasn't appeared after 20 s on screen (APL_BOOT_OK, set by
   launcher.js), it shows them with the version and the screen,
   instead of leaving a black screen nobody can explain. Back closes it.
   ============================================================ */
(function (global) {
    "use strict";

    // v3.3.3 safe mode: 3 start-ups in a row that never reached the Home Screen
    try {
        var bf = parseInt(global.localStorage.getItem("apl.bootFails") || "0", 10) || 0;
        global.APL_SAFE = bf >= 3;
        global.localStorage.setItem("apl.bootFails", String(bf + 1));
        var okWatch = global.setInterval(function () {
            if (global.APL_BOOT_OK) { global.clearInterval(okWatch); try { global.localStorage.setItem("apl.bootFails", "0"); } catch (e) {} }
        }, 2000);
    } catch (e) {}
    var errors = [];
    function note(text) { if (errors.length < 8) errors.push(String(text).slice(0, 220)); }
    global.addEventListener("error", function (e) {
        var where = e.filename ? " (" + String(e.filename).split("/").pop() + ":" + e.lineno + ")" : "";
        note((e.message || "error") + where);
    });
    global.addEventListener("unhandledrejection", function (e) {
        var r = e.reason;
        note("promise: " + (r && r.message ? r.message : r));
    });

    function t(text, vars) { return global.APL && global.APL.t ? global.APL.t(text, vars) : text.replace(/\{(\w+)\}/g, function (m, k) { return vars && k in vars ? vars[k] : m; }); }
    function screen() {
        try {
            var p = global.webapis && global.webapis.productinfo;
            return p ? (p.getRealModel ? p.getRealModel() : p.getModel()) + ", " + p.getFirmware() : "";
        } catch (e) { return ""; }
    }

    // Only the time on screen counts: started in the background (at power-on), the launcher is frozen
    var shownFor = 0, watch = setInterval(function () {
        if (global.APL_BOOT_OK) { clearInterval(watch); return; }
        if (document.hidden || !document.body || ++shownFor < 20) return;
        clearInterval(watch);
        show();
    }, 1000);

    function show() {
        var version = (global.APL_UPDATE && global.APL_UPDATE.running) || (global.APL_BUILD && global.APL_BUILD.version) || "?";
        var box = document.createElement("div");
        box.style.cssText = "position:fixed;left:120px;right:120px;top:120px;z-index:2147483647;padding:40px 48px;border-radius:28px;" +
            "background:#1c1c1e;color:#fff;font:28px/1.45 sans-serif;box-shadow:0 30px 80px rgba(0,0,0,.6)";
        var title = document.createElement("div");
        title.style.cssText = "font-size:40px;font-weight:700;margin-bottom:18px";
        title.textContent = t("Salah Launcher couldn't start");
        var body = document.createElement("div");
        body.textContent = t("Please send a photo of this screen in a GitHub issue, so it can be fixed.");
        var details = document.createElement("pre");
        details.style.cssText = "margin:24px 0 0;white-space:pre-wrap;font:22px/1.4 monospace;color:#c7c7cc";
        details.textContent = "Salah Launcher " + version + (screen() ? " · " + screen() : "") + "\n" +
            (errors.length ? errors.join("\n") : t("No error was reported: the list of apps never came back."));
        box.appendChild(title);
        box.appendChild(body);
        box.appendChild(details);
        document.body.appendChild(box);
        document.addEventListener("keydown", function close(e) {
            if (e.keyCode === 10009 || e.keyCode === 27) { if (box.parentNode) box.parentNode.removeChild(box); document.removeEventListener("keydown", close); }
        });
    }
})(window);

