    function scaleOf() { var v = +sys.pref("prayerWidgetScale"); return (v === 25 || v === 50 || v === 75 || v === 100 || v === 150 || v === 200) ? v : 0; }   /* v7.1.1: up to +200% = 300% of the normal size */
