/* === js/settings.js === */
/* ============================================================
   settings.js — the Settings app, Apple TV–style split view:
   large icon on the left (+ description of the selected row),
   list on the right, selected row in white, values on the right.
   OK enters a submenu / changes a value; Back goes up a level.
   ============================================================ */
(function (global) {
    "use strict";

    var APL = global.APL, sys = APL.sys;
    var root, titleEl, cardEl, descEl, pathEl, listEl, wrapEl, nav;
    var levels = [];
    var listY = 0;
    var isOpen = false;

    function el(tag, cls, html) {
        var e = document.createElement(tag);
        if (cls) e.className = cls;
        if (html !== undefined) e.innerHTML = html;
        return e;
    }

    function buildDom() {
        root = el("section", "settings");
        root.appendChild(el("div", "settings__bg"));
        titleEl = el("h1", "settings__title");
        var hero = el("div", "settings__hero");
        cardEl = el("div", "settings__card");
        descEl = el("p", "settings__desc");
        pathEl = el("p", "settings__path");
        hero.appendChild(cardEl); hero.appendChild(descEl); hero.appendChild(pathEl);
        var wrap = wrapEl = el("div", "settings__listwrap");
        listEl = el("div", "settings__list");
        wrap.appendChild(listEl);
        root.appendChild(titleEl); root.appendChild(hero); root.appendChild(wrap);
        document.body.appendChild(root);

        nav = new APL.Nav({
            onFocus: onFocus,
            onSelect: onSelect,
            onBack: back,
            onKey: onKey,
            onEdge: onEdge,
            /* Radio and every other Settings sub-list must receive each
               physical UP/DOWN event from the Tizen 6.5 remote. */
            rawArrowKeys: true
        });
    }

    function cur() { return levels[levels.length - 1]; }

    /* ---------- values shown on the right ---------- */
    function onOff(v) { return v ? APL.t("On") : APL.t("Off"); }

    /* Without Vetro on the screen (sys.noVetro), the screen's own settings and what closes apps can't work:
       their rows say so instead of "Unavailable" a minute later, or a switch that does nothing. */
    var VETRO_TYPES = { tv: true, tvmode: true, game: true, native: true, service: true };
    function needsVetro(item) { return !!item && sys.noVetro() && (VETRO_TYPES[item.type] || item.vetro === true); }

    function valueHtml(item) {
        switch (item.type) {
            case "info": return item.get();
            case "toggle": return onOff(sys.pref(item.key));
            case "choice":
                var v = sys.pref(item.key);
                for (var i = 0; i < item.options.length; i++) if (item.options[i][0] === v) return item.options[i][1];
                for (var i2 = 0; i2 < item.options.length; i2++) if (v !== undefined && v !== null && String(item.options[i2][0]) === String(v)) return item.options[i2][1];
                return (v === undefined || v === null) ? String(item.options[0][1]) : String(v);
            case "volume":
                var vol = sys.audio.getVolume();
                return '<span class="srow__bar"><i style="width:' + vol + '%"></i></span>' + vol;
            case "mute": return onOff(sys.audio.isMute());
            case "hide": return (sys.pref("hiddenApps").indexOf(item.id) === -1) ? APL.t("Visible") : APL.t("Hidden");
            case "tvmode":
                return sys.tvItem("pictureMode").then(function (it) { return it ? sys.pictureModeName(it.value) : APL.t("Unavailable"); },
                                                      function () { return APL.t("Unavailable"); });
            case "game":
                return sys.game.get().then(function (g) { return onOff(g.on); }, function () { return APL.t("Unavailable"); });
            case "flag": return sys.pref("aerialHidden").indexOf(item.token) === -1 ? APL.t("Show") : APL.t("Hide");
            case "service": return APL.services.isCut(item.group) ? APL.t("Blocked") : APL.t("Active");
            case "native":
                return sys.native.get(item.id).then(function (n) { return nativeText(item, n); }, function () { return APL.t("Unavailable"); });
            default: return "";
        }
    }

    /* Screen setting: a slider, or the list of its values. */
    function nativeText(item, n) {
        if (item.options) {
            for (var i = 0; i < item.options.length; i++) if (item.options[i][0] === n) return item.options[i][1];
            return String(n);
        }
        var d = sys.native.info(item.id);
        var pct = Math.round(100 * (n - d.min) / Math.max(1, d.max - d.min));
        return '<span class="srow__bar"><i style="width:' + pct + '%"></i></span>' + (item.format ? item.format(n) : n);
    }
    function nativeChoice(item, row) {
        var L = cur();
        sys.native.get(item.id).then(function (n) {
            // Two values: OK switches straight from one to the other
            if (item.options.length === 2) {
                var next = item.options[0][0] === n ? item.options[1] : item.options[0];
                // The other screen settings of the menu too: one switch can change another (Start on Salah Launcher, Autorun)
                var slot = row.querySelector(".srow__value");
                if (slot) slot.textContent = "…";                         // the screen is being asked: shown at once
                // Any failure says so, even one thrown before the write starts: "…" must never stay on its own
                Promise.resolve().then(function () { return sys.native.set(item.id, next[0]); })
                    .then(function () { refreshNativeRows(row); },
                          function (e) { APL.toast((e && e.message) || APL.t("The screen refused this setting for now")); refreshNativeRows(row); });
                return;
            }
            var at = 0;
            var opts = item.options.map(function (o, k) {
                if (o[0] === n) at = k;
                return { type: "nativeoption", id: item.id, label: o[1], v: o[0], selected: o[0] === n, desc: item.desc };
            });
            levels.push({ node: { label: item.label, icon: L.node.icon, children: opts }, index: at });
            render("fwd");
        }, function (e) { APL.toast(e.message); });
    }
    /* Slider: the value shown changes right away, the write goes out after the last key press. */
    var nativeTimer = null;
    function nativeSlide(item, row, direction) {
        var d = sys.native.info(item.id), slot = row.querySelector(".srow__value");
        function step(steps) {
            item._value = Math.max(d.min, Math.min(d.max, item._value + steps * (d.step || 1)));
            slot.innerHTML = nativeText(item, item._value);
            clearTimeout(nativeTimer);
            nativeTimer = setTimeout(function () {
                sys.native.set(item.id, item._value).catch(function (e) {
                    APL.toast(e.message);
                    item._value = undefined;
                    fillValue(row);
                });
            }, 350);
        }
        if (item._value !== undefined) { step(direction); return; }
        // Value not read yet: key presses add up while waiting for the screen's answer
        item._steps = (item._steps || 0) + direction;
        if (item._reading) return;
        item._reading = true;
        sys.native.get(item.id).then(function (v) {
            var steps = item._steps;
            item._reading = false;
            item._steps = 0;
            item._value = v;
            step(steps);
        }, function (e) { item._reading = false; item._steps = 0; APL.toast(e.message); });
    }

    function accessory(item) {
        if (needsVetro(item)) return "";
        if (item.type === "menu" || item.type === "choice" || item.type === "tvmode" || (item.type === "native" && item.options && item.options.length > 2)) return APL.icon("chevron", 26, 2.4);
        if (item.type === "nativeoption" && item.selected) return APL.icon("check", 28, 2.6);
        if (item.type === "samsung") return APL.icon("external", 24, 2);
        if ((item.type === "option" || item.type === "tvoption") && item.selected) return APL.icon("check", 28, 2.6);
        return "";
    }

    function tvHtml(item, v) {
        if (v === null || v === undefined) return APL.t("Unavailable");
        var it = item._meta || { min: 0, max: 50 };
        var pct = Math.round(100 * (v - it.min) / Math.max(1, it.max - it.min));
        return '<span class="srow__bar"><i style="width:' + pct + '%"></i></span>' + v;
    }

    function fillValue(row) {
        var item = row._item;
        if (needsVetro(item)) { row.querySelector(".srow__value").textContent = APL.t("Needs Vetro"); return; }
        if (item.type === "tv") {
            var slot0 = row.querySelector(".srow__value");
            slot0.textContent = "…";
            sys.tvItem(item.id).then(function (it) {
                item._meta = it;
                slot0.innerHTML = tvHtml(item, it ? (it.target !== undefined ? it.target : it.value) : null);
            }, function () { slot0.textContent = APL.t("Unavailable"); });
            return;
        }
        var v = valueHtml(item);
        var slot = row.querySelector(".srow__value");
        if (v && typeof v.then === "function") {
            slot.textContent = "…";
            v.then(function (txt) { slot.innerHTML = txt; });
        } else {
            slot.innerHTML = v === undefined || v === null ? "" : v;
        }
    }

    function makeRow(item) {
        var row = el("div", "srow" + (item.type === "info" ? " srow--info" : ""));
        row._item = item;
        row.appendChild(el("span", "srow__label", ""));
        row.firstChild.textContent = item.label;
        row.appendChild(el("span", "srow__value"));
        row.appendChild(el("span", "srow__acc", accessory(item)));
        fillValue(row);
        return row;
    }

    function render(enterDir) {
        var L = cur(), node = L.node;
        titleEl.textContent = node.label;
        // Top level of Settings: Apple's large Settings icon, as on tvOS.
        if (levels.length === 1) {
            // Apple's real Settings icon (fallback: the drawn version)
            var src = global.APL_ASSET ? global.APL_ASSET("images/settings-icon.png") : "images/settings-icon.png";
            cardEl.innerHTML = '<img class="settings__appicon" alt="" src="' + src + '">';
            cardEl.firstChild.onerror = function () { cardEl.innerHTML = APL.settingsArt(430); };
        } else {
            cardEl.innerHTML = APL.icon(node.icon || "gear", 250, 1.3);
        }
        cardEl.classList.toggle("is-app", levels.length === 1);
        listEl.innerHTML = "";
        if (wrapEl) wrapEl.scrollTop = 0;
        listY = 0;
        listEl.style.transform = "translateY(0)";
        // Section titles ("VIDEO", "AUDIO"…): shown, never selectable
        var rows = [];
        node.children.forEach(function (item) {
            if (item.type === "section") {
                var h = el("div", "srow__section");
                h.textContent = item.label;
                listEl.appendChild(h);
                return;
            }
            var r = makeRow(item);
            listEl.appendChild(r);
            rows.push(r);
        });
        // Entry animation on the container: the list keeps its own
        // transform for scrolling (otherwise the animation blocks it).
        if (enterDir) {
            wrapEl.classList.remove("is-enter-fwd", "is-enter-back");
            void wrapEl.offsetWidth;
            wrapEl.classList.add(enterDir === "back" ? "is-enter-back" : "is-enter-fwd");
        }
        var want = L.index || 0;        // setTiles refocuses the 1st row: keep the position we want
        nav.setTiles(rows);
        nav.focus(Math.min(want, rows.length - 1));
    }

    /* ---------- focus ---------- */
    function ensureVisible(row) {
        if (!row) return;
        if (wrapEl) wrapEl.scrollTop = 0;
        // Margins to stay out of the list's top / bottom fade zones.
        var view = 880, top = row.offsetTop, h = row.offsetHeight;
        if (top + listY < 30) listY = -top + 30;
        else if (top + h + listY > view - 80) listY = view - 80 - top - h;
        listEl.style.transform = "translateY(" + listY + "px)";
    }

    function onFocus(i, row) {
        cur().index = i;
        ensureVisible(row);
        var item = row._item;
        descEl.textContent = item.desc || (item.type === "menu" ? "" : "");
        pathEl.style.display = "none";
    }

    function refreshRow(row) { fillValue(row); row.querySelector(".srow__acc").innerHTML = accessory(row._item); }
    function refreshNativeRows(row) {
        var rows = row.parentNode ? row.parentNode.children : [row];
        for (var i = 0; i < rows.length; i++) if (rows[i]._item && rows[i]._item.type === "native") refreshRow(rows[i]);
    }

    function onSelect(i, row) {
        var item = row._item, L = cur();
        if (needsVetro(item)) { APL.toast(APL.t("This needs Vetro, which isn't on this screen.")); return; }
        switch (item.type) {
            case "menu":
                L.index = i;
                levels.push({ node: item, index: 0 });
                render("fwd");
                break;
            case "choice":
                L.index = i;
                var sel = sys.pref(item.key), selIndex = 0;
                var opts = item.options.map(function (o, k) {
                    if (o[0] === sel) selIndex = k;
                    return { type: "option", label: o[1], v: o[0], key: item.key, apply: item.apply, selected: o[0] === sel, desc: item.desc };
                });
                levels.push({ node: { label: item.label, icon: L.node.icon, children: opts }, index: selIndex });
                render("fwd");
                break;
            case "option":
                sys.setPref(item.key, item.v);
                if (item.apply) item.apply(item.v);
                back();
                break;
            case "toggle":
                sys.setPref(item.key, !sys.pref(item.key));
                refreshRow(row);
                break;
            case "flag":
                var off = sys.pref("aerialHidden").slice(), at = off.indexOf(item.token);
                if (at === -1) off.push(item.token); else off.splice(at, 1);
                sys.setPref("aerialHidden", off);
                refreshRow(row);
                break;
            case "mute":
                sys.audio.setMute(!sys.audio.isMute());
                refreshRow(row);
                break;
            case "hide":
                var hidden = sys.pref("hiddenApps").slice();
                var k = hidden.indexOf(item.id);
                if (k === -1) hidden.push(item.id); else hidden.splice(k, 1);
                sys.setPref("hiddenApps", hidden);
                refreshRow(row);
                if (APL.reloadApps) APL.reloadApps();
                break;
            case "samsung":
                sys.openSamsungSettings().catch(function (e) { APL.toast(e.message); });
                break;
            case "tvmode":
                L.index = i;
                sys.tvItem("pictureMode").then(function (it) {
                    var curMode = it ? it.value : null, at = 0;
                    var modes = sys.PICTURE_MODES.map(function (m, n) {
                        if (m[0] === curMode) at = n;
                        return { type: "tvoption", label: m[1], v: m[0], selected: m[0] === curMode, desc: item.desc };
                    });
                    levels.push({ node: { label: item.label, icon: L.node.icon, children: modes }, index: at });
                    render("fwd");
                }, function (e) { APL.toast(e.message); });
                break;
            case "tvoption":
                sys.setPictureMode(item.v).then(function () {
                    APL.toast(APL.t("Picture Mode: {mode}", { mode: item.label }), true);
                    back();
                }, function (e) { APL.toast(e.message); });
                break;
            case "game":
                sys.game.get().then(function (g) {
                    return sys.game.set(!g.on);
                }).then(function (g) {
                    APL.toast(g.pending ? APL.t("Game Mode requested: it will turn on as soon as you switch to HDMI or USB-C")
                                        : (g.on ? APL.t("Game Mode on") : APL.t("Game Mode off")), true);
                    refreshRow(row);
                }, function (e) { APL.toast(e.message); });
                break;
            case "native":
                L.index = i;
                if (item.options) nativeChoice(item, row);
                break;
            case "nativeoption":
                sys.native.set(item.id, item.v).then(function () { back(); }, function (e) { APL.toast(e.message); });
                break;
            case "service":
                APL.services.toggle(item.group).then(function () { refreshRow(row); });
                break;
            case "action":
                item.run();
                break;
            default: break;
        }
    }

    function onKey(code) {
        /* Settings is an ordered vertical list. Do not hand UP/DOWN to the
           generic nearest-rectangle algorithm: while a long list is translated
           during scrolling, stale geometry can make it find no neighbour. An
           explicit list step is deterministic and leaves LEFT, RIGHT, OK and
           Back to their existing handlers. */
        if ((code === APL.KEY.UP || code === APL.KEY.DOWN) && nav && nav.tiles && nav.tiles.length > 1) {
            var direction = code === APL.KEY.UP ? -1 : 1;
            var next = (nav.index + direction + nav.tiles.length) % nav.tiles.length;
            nav.focus(next);
            if (APL.sound) APL.sound.tick();
            return true;
        }

        var row = nav.current();
        // A slider of the screen's settings without Vetro: ◀ ▶ do nothing (no request that can't be answered)
        if (row && (row._item.type === "native" || row._item.type === "tv") && needsVetro(row._item) &&
            (code === APL.KEY.LEFT || code === APL.KEY.RIGHT)) return true;
        if (row && row._item.type === "native" && !row._item.options && (code === APL.KEY.LEFT || code === APL.KEY.RIGHT)) {
            nativeSlide(row._item, row, code === APL.KEY.RIGHT ? 1 : -1);
            return true;
        }
        if (row && row._item.type === "tv" && (code === APL.KEY.LEFT || code === APL.KEY.RIGHT)) {
            var item = row._item;
            sys.tvAdjust(item.id, code === APL.KEY.RIGHT ? 1 : -1, function (nv) {
                row.querySelector(".srow__value").innerHTML = tvHtml(item, nv);
            }).catch(function (e) { APL.toast(e.message); });
            return true;
        }
        if (!row || row._item.type !== "volume") return false;
        if (code === APL.KEY.LEFT || code === APL.KEY.RIGHT) {
            sys.audio.setVolume(sys.audio.getVolume() + (code === APL.KEY.RIGHT ? 1 : -1));
            fillValue(row);
            return true;
        }
        return false;
    }

    function onEdge(dir) {
        if (!nav || !nav.tiles || nav.tiles.length <= 1) return;
        if (dir === "up" && nav.index === 0) {
            nav.focus(nav.tiles.length - 1);
            if (APL.sound) APL.sound.tick();
        } else if (dir === "down" && nav.index === nav.tiles.length - 1) {
            nav.focus(0);
            if (APL.sound) APL.sound.tick();
        }
    }

    function back() {
        if (levels.length > 1) { levels.pop(); render("back"); }
        else close();
    }

    /* ---------- open / close ---------- */
    /* sectionLabel: the English name of a top-level menu ("Connection"), translated or not. */
    function open(sectionLabel) {
        if (!root) buildDom();
        levels = [{ node: APL.settingsTree(), index: 0 }];
        if (sectionLabel) {
            var kids = levels[0].node.children;
            for (var i = 0; i < kids.length; i++) {
                if ((kids[i].label === sectionLabel || kids[i].label === APL.t(sectionLabel)) && kids[i].type === "menu") {
                    levels[0].index = i;
                    levels.push({ node: kids[i], index: 0 });
                    break;
                }
            }
        }
        render();
        // Performance mode: background = pre-blurred artwork of the selected app (no live blur).
        var bl = document.getElementById("bgBlur"), bgEl = root.firstChild;
        bgEl.style.background = (document.body.classList.contains("perf") && bl && bl.style.background)
            ? "linear-gradient(160deg, rgba(36,84,168,0.62), rgba(10,26,66,0.86)), " + bl.style.background
            : "";
        root.classList.add("is-open");
        document.body.classList.add("has-settings");
        APL.pushNav(nav);
        isOpen = true;
    }

    function close() {
        if (!root) return;
        root.classList.remove("is-open");
        document.body.classList.remove("has-settings");
        APL.popNav(nav);
        isOpen = false;
    }

    APL.settings = { open: open, close: close, isOpen: function () { return isOpen; } };
})(window);

/* === js/controlcenter.js === */
/* ============================================================
   controlcenter.js — Control Center in the style of tvOS 26 / 27.

   Glass tiles float at the top right, over the Home Screen:
     Sleep (large square) · Wi-Fi · Do Not Disturb
     Audio (sound output: screen, AirPods…) · Sleep Timer
     ○ Game Mode (direct)  ○ Accessibility  ○ AirPlay and iPhone  ○ Sources
     Brightness (real, through Vetro)
     Screen Saver · Settings
   "Audio" opens the list of outputs: the screen's speakers and paired
   Bluetooth devices (AirPods, headphones, speakers), connected with one
   click, and the search to pair new ones, right here.
   "AirPlay and iPhone" explains screen mirroring and the iPhone as a
   remote.

   Opening: Play/Pause, holding Home or the red button (C on the keyboard
   in the preview). Closing: the same button or Back.
   ============================================================ */
(function (global) {
    "use strict";

    var APL = global.APL, sys = APL.sys, K = APL.KEY;
    var root, panel, timeEl, avatarEl, viewport, body, captionEl, nav;
    var items = [], view = "main", lastMainIndex = 1, scrollY = 0;
    var isOpen = false;

    var TIMERS = [0, 15, 30, 60, 90, 120];
    var ALL = APL.t("All Settings"), CNX = ALL + " › " + APL.t("Connection");

    function el(tag, cls, html) {
        var e = document.createElement(tag);
        if (cls) e.className = cls;
        if (html !== undefined) e.innerHTML = html;
        return e;
    }

    function samsung(path, hint) {
        return function () {
            sys.openSamsungSettings(path).then(function () {
                close();
                APL.toast(hint || APL.t("Samsung settings opened — {path}", { path: path }), true);
            }, function (e) { APL.toast(e.message); });
        };
    }
    function openSettings(section) { return function () { close(); APL.settings.open(section); }; }

    function remaining() {
        var at = sys.pref("sleepAt");
        if (!at) return APL.t("Not set");
        return Math.max(1, Math.round((at - Date.now()) / 60000)) + " min";
    }

    /* ---------- Bluetooth (AirPods, headphones, speakers) ----------
       The screen has no BlueZ on D-Bus: the list, the search and pairing go through
       the Tizen API (tizen.bluetooth), the sound connection through Samsung's Bluetooth
       manager (root command through Vetro). */
    var BT_MGR = "gdbus call --system --dest com.samsung.tv.bt.connectionmanager --object-path /com/samsung/tv/bt/connectionmanager --method ";
    var BT_ADDR = /^[0-9A-F]{2}(:[0-9A-F]{2}){5}$/i;
    var AUDIO_NAME = /airpods|beats|buds|casque|headphone|headset|écouteur|ecouteur|enceinte|speaker|soundbar|barre de son|sony|bose|jbl|marshall|sennheiser/i;
    var PHONE_NAME = /airpods|buds|casque|headphone|headset|écouteur|ecouteur|beats/i;
    var bt = { list: null, at: 0, failed: false, busy: false };
    var scan = { on: false, found: {}, pairing: null };
    var keepFocus = false;                     // after a connection: focus stays on the same row

    // PC preview: examples (not real devices)
    var MOCK_BT = [
        { address: "mock1", name: "AirPods Pro", kind: "headphones", connected: false, battery: 95 },
        { address: "mock2", name: APL.t("Soundbar"), kind: "speaker", connected: false, battery: null }
    ];
    var MOCK_SCAN = [{ address: "mock3", name: APL.t("Demo AirPods"), kind: "headphones" }];

    function adapter() {
        try { return global.tizen.bluetooth.getDefaultAdapter(); } catch (e) { return null; }
    }

    /* Bluetooth class: 4 = audio and video; 1, 2 and 6 = headset, hands-free kit, headphones. */
    function kindOf(d) {
        var cls = d.deviceClass || {}, name = d.name || "";
        if (PHONE_NAME.test(name) || (cls.major === 4 && (cls.minor === 1 || cls.minor === 2 || cls.minor === 6))) return "headphones";
        if (cls.major === 4 || AUDIO_NAME.test(name)) return "speaker";
        return null;                                         // sound only (not controllers, keyboards…)
    }
    function devOf(d) {
        return { address: d.address, name: d.name || APL.t("Bluetooth device"), kind: kindOf(d),
                 connected: !!d.isConnected, bonded: !!d.isBonded, battery: null };
    }

    function btRefresh(force) {
        if (sys.PREVIEW) { bt.list = MOCK_BT; bt.failed = false; return Promise.resolve(bt.list); }
        if (!force && bt.list && Date.now() - bt.at < 15000) return Promise.resolve(bt.list);
        return new Promise(function (resolve, reject) {
            var a = adapter();
            if (!a) { reject(new Error("unavailable")); return; }
            a.getKnownDevices(resolve, reject);
        }).then(function (list) {
            // Paired devices only: the screen's list also keeps those seen during a search
            bt.list = list.map(devOf).filter(function (d) { return d.kind && d.bonded; });
            bt.at = Date.now(); bt.failed = false;
            // Who receives the sound: Samsung's manager knows, not Tizen's "isConnected"
            return sys.exec(BT_MGR + "org.tizen.btapp.ApiInterface.get_connected_bt_speaker_info 2>&1").then(function (r) {
                var on = String(r.output || "").toUpperCase();
                bt.list.forEach(function (d) { d.connected = on.indexOf(d.address.toUpperCase()) !== -1; });
                return bt.list;
            }, function () { return bt.list; });
        }).catch(function () { bt.failed = true; bt.list = bt.list || []; return bt.list; });
    }

    /* Waits for the device to reach the wanted state: Bluetooth answers within a few seconds. */
    function btWait(address, connected, tries) {
        return btRefresh(true).then(function () {
            var now = (bt.list || []).filter(function (d) { return d.address === address; })[0];
            if (!!(now && now.connected) === connected || tries <= 0) return now;
            return new Promise(function (r) { setTimeout(r, 1500); }).then(function () { return btWait(address, connected, tries - 1); });
        });
    }

    function btDone() {
        bt.busy = false;
        if (isOpen && view === "audio") { keepFocus = true; render(); keepFocus = false; }
    }

    function btConnect(dev) {
        bt.busy = true;
        APL.toast(APL.t("Connecting to “{name}”…", { name: dev.name }), true);
        // replace_current_bluetooth_speaker returns 0 but does nothing when no device is already connected
        sys.exec(BT_MGR + "org.tizen.btapp.ApiInterface.buds_switching_connect " + dev.address + " 2>&1").catch(function () {}).then(function () {
            return btWait(dev.address, true, 10);
        }).then(function (now) {
            if (now && now.connected) APL.toast(APL.t("Sound on “{name}”", { name: now.name }), true);
            else APL.toast(APL.t("“{name}” isn't responding: open the case or turn on the headphones, then try again.", { name: dev.name }));
            btDone();
        });
    }

    function btDisconnect(dev) {
        bt.busy = true;
        APL.toast(APL.t("Disconnecting “{name}”…", { name: dev.name }), true);
        // buds_switching_disconnect returns 12 and disconnects nothing
        sys.exec(BT_MGR + "org.tizen.btapp.ApiInterface.disconnect_last_btspk_list 2>&1").catch(function () {}).then(function () {
            return btWait(dev.address, false, 6);
        }).then(function (now) {
            if (now && now.connected) APL.toast(APL.t("“{name}” is still connected: try again in a moment.", { name: dev.name }));
            else APL.toast(APL.t("Sound on the screen's speakers"), true);
            btDone();
        });
    }

    function btToggle(dev) {
        if (bt.busy) return;
        if (sys.PREVIEW) {
            MOCK_BT.forEach(function (d) { d.connected = d === dev ? !d.connected : false; });
            APL.toast(dev.connected ? APL.t("Sound on “{name}”", { name: dev.name }) : APL.t("“{name}” disconnected", { name: dev.name }), true);
            render(); return;
        }
        if (!BT_ADDR.test(dev.address)) return;
        if (dev.connected) btDisconnect(dev); else btConnect(dev);
    }

    /* Forget a device (long press on its row): it will need to be paired again. */
    function btForget(dev) {
        if (!dev || sys.PREVIEW) return;
        APL.alert({
            title: APL.t("Forget “{name}”?", { name: dev.name }),
            message: APL.t("You'll need to pair it again to use it."),
            buttons: [
                { label: APL.t("Cancel") },
                { label: APL.t("Forget"), destructive: true, run: function () {
                    var a = adapter();
                    if (!a) return;
                    a.destroyBonding(dev.address, function () {
                        APL.toast(APL.t("“{name}” forgotten", { name: dev.name }), true);
                        btRefresh(true).then(function () { if (isOpen && view === "audio") render(); });
                    }, function (e) { APL.toast(APL.t("Couldn't forget this device: {error}", { error: e.message })); });
                } }
            ],
            focus: 0
        });
    }

    /* ---------- search and pairing, right here ---------- */
    function paintPair() { if (isOpen && view === "pair") render(); }

    function scanStop() {
        if (!scan.on) return;
        scan.on = false;
        var a = adapter();
        if (a) { try { a.stopDiscovery(function () {}, function () {}); } catch (e) {} }
    }

    function scanStart() {
        scan.found = {};
        if (sys.PREVIEW) {
            scan.on = false;
            MOCK_SCAN.forEach(function (d) { scan.found[d.address] = d; });
            paintPair();
            return;
        }
        var a = adapter();
        if (!a) { APL.toast(APL.t("Bluetooth unavailable on this screen")); return; }
        function ended() { scan.on = false; paintPair(); }
        try {
            scan.on = true;
            a.discoverDevices({
                onstarted: function () { paintPair(); },
                ondevicefound: function (d) {
                    if (d.isBonded || !d.name) return;               // already paired: it is in the Audio list
                    var dev = devOf(d);
                    if (!dev.kind || scan.found[dev.address]) return;
                    scan.found[dev.address] = dev;
                    paintPair();
                },
                ondevicedisappeared: function () {},
                onfinished: ended
            }, function (e) { ended(); APL.toast(APL.t("Search failed: {error}", { error: e.message })); });
        } catch (e) { ended(); APL.toast(APL.t("Search failed: {error}", { error: e.message })); }
    }

    function btPair(dev) {
        if (scan.pairing) return;
        if (sys.PREVIEW) { APL.toast(APL.t("Preview: “{name}” would be paired", { name: dev.name }), true); return; }
        var a = adapter();
        if (!a || !BT_ADDR.test(dev.address)) return;
        scan.pairing = dev.address;
        scanStop();
        APL.toast(APL.t("Pairing “{name}”…", { name: dev.name }), true);
        try {
            a.createBonding(dev.address, function (d) {
                scan.pairing = null;
                var done = devOf(d);
                APL.toast(APL.t("“{name}” is paired", { name: done.name }), true);
                btRefresh(true).then(function () {
                    if (isOpen && view === "pair") show("audio");
                    btConnect(done);
                });
            }, function (e) {
                scan.pairing = null;
                APL.toast(APL.t("“{name}” couldn't be paired: put it back in pairing mode, then try again. ({error})", { name: dev.name, error: e.message }));
                paintPair();
            });
        } catch (e) {
            scan.pairing = null;
            APL.toast(APL.t("Pairing failed: {error}", { error: e.message }));
        }
    }

    /* ---------- Game Mode ---------- */
    var gameState = { on: false, pending: false, busy: false };
    function gameRefresh() {
        return sys.game.get().then(function (g) {
            gameState.on = g.on;
            gameState.pending = !!g.pending;
            if (isOpen && view === "main") refresh();
        }, function () {});
    }
    function gameToggle() {
        if (gameState.busy) return;
        gameState.busy = true;
        var want = !gameState.on;
        APL.toast(want ? APL.t("Turning on Game Mode…") : APL.t("Turning off Game Mode…"), true);
        sys.game.set(want).then(function (g) {
            gameState.busy = false;
            gameState.on = g.on;
            gameState.pending = !!g.pending;
            if (g.pending) APL.toast(APL.t("Game Mode requested: it will turn on as soon as you switch to HDMI or USB-C"), true);
            else APL.toast(g.on ? APL.t("Game Mode on") : APL.t("Game Mode off"), true);
            if (isOpen) refresh();
            // Game Mode has its own brightness: the slider picks up the screen's
            nav.tiles.forEach(function (t) {
                if (t._item.type === "backlight") sys.tvItem("backlight").then(function (m) { if (m) drawBacklight(t, m.value, m); }, function () {});
            });
        }, function (e) {
            gameState.busy = false;
            APL.toast(e.message);
        });
    }

    function speakersToTv() {
        var on = (bt.list || []).filter(function (d) { return d.connected; });
        if (!on.length) { APL.toast(APL.t("Sound is already coming from the screen"), true); return; }
        on.forEach(btToggle);
    }

    function outputName() {
        var on = (bt.list || []).filter(function (d) { return d.connected; })[0];
        return on ? on.name : APL.t("TV Speakers");
    }

    /* ---------- views ---------- */
    function mainItems() {
        return [
            { cls: "big", icon: "power", title: APL.t("Sleep"),
              select: function () { sys.sleepNow().catch(function (e) { APL.toast(e.message); }); } },
            { cls: "pill", icon: "wifi", title: "Wi-Fi", tint: "#0a84ff",
              sub: function () { var n = sys.network(); return n.connected ? (n.type === "Wi-Fi" ? n.ssid : n.type) : APL.t("Disconnected"); },
              on: function () { return sys.network().connected; }, select: openSettings(APL.t("Connection")) },
            { cls: "pill", icon: "moon", title: APL.t("Do Not Disturb"), tint: "#5e5ce6",
              sub: function () { return sys.pref("dnd") ? APL.t("On") : APL.t("Off"); },
              on: function () { return sys.pref("dnd"); }, select: function () { sys.setPref("dnd", !sys.pref("dnd")); } },
            { cls: "pill", icon: "airplayAudio", title: "Audio", sub: outputName, select: function () { show("audio"); } },
            { cls: "pill", icon: "timer", title: APL.t("Sleep Timer"), tint: "#ff9f0a", sub: remaining,
              on: function () { return !!sys.pref("sleepAt"); },
              select: function () {
                  var i = TIMERS.indexOf(sys.pref("sleepTimer"));
                  var next = TIMERS[(i + 1) % TIMERS.length];
                  sys.armSleepTimer(next);
                  APL.toast(next ? APL.t("Going to sleep in {n} min", { n: next }) : APL.t("Sleep Timer off"), true);
              } },
            { cls: "round", icon: "gamepad", title: APL.t("Game Mode"), tint: "#30d158",
              sub: function () { return gameState.pending ? APL.t("When you switch to HDMI or USB-C") : gameState.on ? APL.t("On") : APL.t("Off"); },
              on: function () { return gameState.on; }, select: gameToggle },
            { cls: "round", icon: "access", title: APL.t("Accessibility"), select: openSettings(APL.t("General & Privacy")) },
            { cls: "round", icon: "airplay", title: APL.t("AirPlay and iPhone"), select: function () { show("airplay"); } },
            { cls: "round", icon: "source", title: "Sources", select: function () { close(); APL.openSources(); } },
            { cls: "slider", type: "backlight", icon: "sun", title: APL.t("Brightness") },
            { cls: "pill", icon: "airplayAudio", title: APL.t("Quran Radio"), tint: "#0f8a5f",
              sub: function () { return APL.radio && APL.radio.isPlaying() ? APL.t("Playing") : APL.t("Stopped"); },
              on: function () { return !!(APL.radio && APL.radio.isPlaying()); },
              select: function () {
                  if (!APL.radio) return;
                  APL.radio.toggle().then(function () { show("main"); }, function (e) { APL.toast(e.message); });
              } },
            { cls: "pill", icon: "timer", title: APL.t("Tasks"), tint: "#2563eb",
              sub: function () {
                  var nx = APL.tasks && APL.tasks.next();
                  return nx ? APL.tasks.left(nx.ms) : APL.t("Add Task");
              },
              on: function () { return !!(APL.tasks && APL.tasks.next()); },
              select: function () { close(); if (APL.tasksPage) APL.tasksPage.open(); } },
            { cls: "pill", icon: "photo", title: APL.t("Screensaver"), sub: function () { return APL.t("Start"); },
              select: function () { close(); if (APL.screensaver) APL.screensaver.start(); } },
            { cls: "pill", icon: "gear", title: APL.t("Settings"), sub: function () { return APL.t("All settings"); },
              select: openSettings() },
            { cls: "round", icon: "search", title: APL.t("Search"), start: true,
              select: function () { close(); if (APL.search) APL.search.open(); } }
        ];
    }

    function audioItems() {
        var list = bt.list || [], out = [{ cls: "head", title: "Audio" }];
        var phones = list.filter(function (d) { return d.kind === "headphones"; });
        var speakers = list.filter(function (d) { return d.kind === "speaker"; });
        var any = list.some(function (d) { return d.connected; });
        function devRow(d) {
            return { cls: "row", icon: d.kind === "headphones" ? "headphones" : "speaker", title: d.name,
                     sub: function () { return (d.connected ? APL.t("Connected") : APL.t("Not connected")) + (d.battery != null ? " · " + d.battery + " %" : ""); },
                     check: function () { return d.connected; }, select: function () { btToggle(d); },
                     hold: function () { btForget(d); } };
        }
        if (phones.length) {
            out.push({ cls: "section", title: APL.t("Headphones") });
            phones.forEach(function (d) { out.push(devRow(d)); });
        }
        out.push({ cls: "section", title: APL.t("Speakers") });
        out.push({ cls: "row", icon: "display", title: APL.t("TV Speakers"), sub: function () { return APL.t("Samsung screen"); },
                   check: function () { return !any; }, select: speakersToTv });
        speakers.forEach(function (d) { out.push(devRow(d)); });
        out.push({ cls: "section", title: bt.failed ? APL.t("Bluetooth list unavailable") : APL.t("Other Devices") });
        out.push({ cls: "row", icon: "bluetooth", title: APL.t("Pair AirPods or Headphones…"),
                   sub: function () { return APL.t("Searches for nearby devices"); },
                   select: function () { show("pair"); } });
        return out;
    }

    function pairItems() {
        var out = [{ cls: "head", title: APL.t("Pair a Device") }];
        var found = Object.keys(scan.found).map(function (k) { return scan.found[k]; });
        out.push({ cls: "section", title: scan.on ? APL.t("Searching…") : APL.t("Devices Found") });
        found.forEach(function (d) {
            out.push({ cls: "row", icon: d.kind === "headphones" ? "headphones" : "speaker", title: d.name,
                       sub: function () { return scan.pairing === d.address ? APL.t("Pairing…") : APL.t("OK to pair"); },
                       select: function () { btPair(d); } });
        });
        if (!found.length && !scan.on) {
            out.push({ cls: "row", icon: "bluetooth", title: APL.t("No Devices Found"),
                       sub: function () { return APL.t("Make sure it's in pairing mode"); } });
        }
        out.push({ cls: "section", title: APL.t("AirPods: case open, button on the back held down") });
        out.push({ cls: "row", icon: "bluetooth", title: scan.on ? APL.t("Searching…") : APL.t("Search Again"),
                   sub: function () { return APL.t("Takes a few dozen seconds"); },
                   select: function () { if (!scan.on) scanStart(); } });
        return out;
    }

    function airplayItems() {
        return [
            { cls: "head", title: APL.t("AirPlay and iPhone") },
            { cls: "section", title: APL.t("From iPhone") },
            { cls: "row", icon: "split", title: APL.t("Mirror the Screen"),
              sub: function () { return APL.t("Control Center › Screen Mirroring › this screen"); } },
            { cls: "row", icon: "airplay", title: APL.t("Send a Video or Photos"),
              sub: function () { return APL.t("AirPlay button in the app, then choose this screen"); } },
            { cls: "row", icon: "remote", title: APL.t("iPhone as a Remote"),
              sub: function () { return APL.t("Home app: add the screen, then Control Center › Remote"); } },
            { cls: "row", icon: "lock", title: APL.t("Connection Code"),
              sub: function () { return APL.t("The screen shows it when the iPhone connects · set it in: Require Code"); },
              select: samsung(CNX + " › " + APL.t("Apple AirPlay Settings") + " › " + APL.t("Require Code")) },
            { cls: "section", title: APL.t("On the Screen") },
            { cls: "row", icon: "gear", title: APL.t("AirPlay and HomeKit Settings"),
              sub: function () { return APL.t("Screen name, passcode, HomeKit"); },
              select: samsung(CNX + " › " + APL.t("Apple AirPlay Settings")) }
        ];
    }

    function show(v) {
        if (view === "main") lastMainIndex = nav.index;
        view = v;
        if (v === "audio") { render(); btRefresh(true).then(function () { if (isOpen && view === "audio") render(); }); return; }
        render();
        if (v === "pair") scanStart();
    }

    /* ---------- rendering ---------- */
    /* A tile's content is written without touching its glass. innerHTML also wiped
       the pane glass.js lays in each tile, and the Control Center redraws every
       tile every 15 s and after each OK: all the buttons showed their plain fill
       until their panes came back, half a second on the M8. Content that has not
       changed is not written at all. */
    function fill(t, html) {
        if (t.__html === html) return;
        t.__html = html;
        var panes = [], i;
        for (i = 0; i < t.children.length; i++) {
            if (t.children[i].classList.contains("cg__glass")) panes.push(t.children[i]);
        }
        t.innerHTML = html;
        for (i = panes.length - 1; i >= 0; i--) t.insertBefore(panes[i], t.firstChild);
    }

    function draw(it, t) {
        if (it.cls === "avatar") return;
        var on = it.on && it.on();
        t.classList.toggle("is-on", !!on);
        if (it.tint) t.style.setProperty("--tint", it.tint);
        if (it.cls === "slider") { drawBacklight(t, null, null); return; }
        if (it.cls === "round") { fill(t, APL.icon(it.icon, 44, 1.9)); return; }
        if (it.cls === "big") {
            fill(t, '<span class="cc__bigico">' + APL.icon(it.icon, 92, 1.7) + '</span><span class="cc__title">' + it.title + '</span>');
            return;
        }
        var check = it.check ? '<span class="cc__check">' + (it.check() ? APL.icon("check", 30, 2.6) : "") + '</span>' : "";
        fill(t, '<span class="cc__ico">' + APL.icon(it.icon, it.cls === "row" ? 32 : 38, 2) + '</span>' +
            '<span class="cc__txt"><span class="cc__title">' + it.title + '</span>' +
            (it.sub ? '<span class="cc__sub">' + it.sub() + '</span>' : '') + '</span>' + check);
    }

    function drawBacklight(t, v, meta) {
        var pct = (v === null || !meta) ? 0 : Math.round(100 * (v - meta.min) / Math.max(1, meta.max - meta.min));
        fill(t, '<span class="cc__ico">' + APL.icon("sun", 38, 2) + '</span>' +
            '<span class="cc__bar"><i style="width:' + pct + '%"></i></span>' +
            '<span class="cc__val">' + (v === null ? "—" : v) + '</span>');
    }

    function render() {
        var keep = nav.index;                  // Bluetooth search: the list grows, focus stays in place
        items = view === "main" ? mainItems() : view === "audio" ? audioItems() : view === "pair" ? pairItems() : airplayItems();
        body.innerHTML = "";
        body.className = "cc__body cc__body--" + view;
        scrollY = 0;
        body.style.transform = "translateY(0)";
        var focusables = [], rounds = null;
        captionEl = null;
        items.forEach(function (it) {
            if (it.cls === "head") {
                var h = el("div", "cc__sheethead", APL.icon("chevron", 30, 2.6) + "<span></span>");
                h.lastChild.textContent = it.title;
                body.appendChild(h);
                return;
            }
            if (it.cls === "section") {
                var s = el("div", "cc__section");
                s.textContent = it.title;
                body.appendChild(s);
                return;
            }
            var t = el("div", "cc__t cc__t--" + it.cls);
            t._item = it;
            draw(it, t);
            if (it.cls === "round") {
                if (!rounds) { rounds = el("div", "cc__rounds"); body.appendChild(rounds); }
                if (it.start) rounds.style.justifyContent = "flex-start";      // Search sits at the left edge
                rounds.appendChild(t);
            } else {
                if (rounds && it.cls !== "round") {
                    captionEl = el("div", "cc__caption");
                    captionEl.__group = rounds;             // the circles this label names
                    body.appendChild(captionEl);
                    rounds = null;
                }
                body.appendChild(t);
            }
            focusables.push(t);
        });
        /* A row with one circle (Search sits on its own) does not need the height
           of a row of four: it stays the small button it was. */
        [].forEach.call(body.querySelectorAll(".cc__rounds"), function (r) {
            if (r.children.length === 1) r.classList.add("cc__rounds--solo");
        });
        /* A round row can be the last group (Search sits on its own): it needs
           its caption all the same, since the circles carry no label. */
        if (rounds) {
            captionEl = el("div", "cc__caption");
            captionEl.__group = rounds;
            body.appendChild(captionEl);
        }
        focusables.forEach(function (t) {
            if (t._item.type === "backlight") {
                sys.tvItem("backlight").then(function (m) {
                    if (m) drawBacklight(t, m.target !== undefined ? m.target : m.value, m);
                }, function () {});
            }
        });
        if (view === "main") {
            // The avatar at the top right: the household's profiles
            avatarEl._item = { cls: "avatar", title: APL.t("Profiles"), select: function () { close(); if (APL.profilesUI) APL.profilesUI.open(); } };
            focusables.unshift(avatarEl);
        }
        nav.setTiles(focusables);
        var start = view === "main" ? Math.min(lastMainIndex, focusables.length - 1) : 0;
        // Audio sub-panel: the connected device first, as on tvOS
        if (view === "audio" && !keepFocus) focusables.forEach(function (t, i) { if (t._item.check && t._item.check() && !start) start = i; });
        if (view === "pair" || keepFocus) start = Math.min(keep || 0, focusables.length - 1);
        nav.focus(start);
        paintCaption(nav.current());
        /* The new tiles get their glass in this same frame: waiting for glass.js
           to notice them showed their plain fill for a moment as the panel opened. */
        if (APL.glass && APL.glass.paint) APL.glass.paint();
    }

    function captionOf(it) {
        if (!it || it.cls !== "round") return "";
        return it.sub ? it.title + " · " + it.sub() : it.title;
    }

    /* The round buttons carry no label of their own, so the row under them does.
       There is more than one round row (Game Mode… Sources, then Search), so the
       label is written on the caption that belongs to the focused circle's row
       and every other one is left empty. */
    function paintCaption(t) {
        var caps = body ? body.querySelectorAll(".cc__caption") : [], i, g;
        for (i = 0; i < caps.length; i++) {
            g = caps[i].__group;
            caps[i].textContent = (t && g && g.contains(t)) ? captionOf(t._item) : "";
        }
    }

    function refresh() {
        nav.tiles.forEach(function (t) { if (t._item.type !== "backlight") draw(t._item, t); });
        paintCaption(nav.current());
        var d = new Date(), h = d.getHours(), m = ((d.getMinutes()) < 10 ? "0" : "") + d.getMinutes();
        timeEl.textContent = sys.pref("clock24") ? ((h) < 10 ? "0" : "") + h + ":" + m : ((h % 12) || 12) + ":" + m;
        if (APL.profilesUI) APL.profilesUI.paint(avatarEl, sys.profiles.current());
    }

    function ensureVisible(t) {
        var view = (viewport && viewport.clientHeight ? viewport.clientHeight - 24 : 800), top = t.offsetTop, h = t.offsetHeight;
        if (top + scrollY < 0) scrollY = -top + 10;
        else if (top + h + scrollY > view) scrollY = view - top - h;
        body.style.transform = "translateY(" + scrollY + "px)";
    }

    function buildDom() {
        root = el("section", "cc");
        root.appendChild(el("div", "cc__dim"));
        panel = el("div", "cc__panel");
        var head = el("header", "cc__head");
        timeEl = el("div", "cc__time");
        var icons = el("div", "cc__heads");
        icons.appendChild(el("span", "cc__headico", APL.icon("sliders", 28, 2)));
        avatarEl = el("span", "cc__avatar");
        icons.appendChild(avatarEl);
        head.appendChild(timeEl); head.appendChild(icons);
        viewport = el("div", "cc__viewport");
        body = el("div", "cc__body");
        viewport.appendChild(body);
        panel.appendChild(head); panel.appendChild(viewport);
        root.appendChild(panel);
        document.body.appendChild(root);

        nav = new APL.Nav({
            rows: true,     /* v7.0.5: LEFT/RIGHT stay in the row (no diagonal jumps in the tile grid) */
            onFocus: function (i, t) {
                ensureVisible(t);
                paintCaption(t);
            },
            onSelect: function (i, t) {
                var it = t._item;
                if (it.type === "backlight") {
                    sys.tvItem("backlight").then(function (m) { if (!m || !m.writable) APL.toast(APL.t("Brightness unavailable right now")); },
                                                 function (e) { APL.toast(e.message); });
                    return;
                }
                if (it.select) it.select();
                if (isOpen && nav.tiles.indexOf(t) !== -1) refresh();
            },
            canHold: function (i) { var t = nav.tiles[i]; return !!(t && t._item && t._item.hold); },
            onLongPress: function (i, t) { if (t._item.hold) t._item.hold(); },
            onBack: function () {
                if (view === "pair") { scanStop(); show("audio"); return; }
                if (view !== "main") { view = "main"; render(); return; }
                close();
            },
            onKey: function (code) {
                var t = nav.current(), it = t && t._item;
                if (it && it.type === "backlight" && (code === K.LEFT || code === K.RIGHT)) {
                    sys.tvAdjust("backlight", code === K.RIGHT ? 2 : -2, function (v, meta) { drawBacklight(t, v, meta); })
                        .catch(function (e) { APL.toast(e.message); });
                    return true;
                }
                return false;
            }
        });
    }

    function open() {
        if (!root) buildDom();
        view = "main";
        lastMainIndex = 2;                      // Wi-Fi (after the avatar and Sleep): never "Sleep" by mistake
        render();
        refresh();
        root.classList.add("is-open");
        document.body.classList.add("has-cc");
        try { if (APL.glass && APL.glass.paint) APL.glass.paint(); } catch (e) {}      // v8.6.6: the tiles' glass in the same frame as the panel, not 40-90 ms later
        APL.pushNav(nav);
        isOpen = true;
        btRefresh(false).then(function () { if (isOpen && view === "main") refresh(); });
        gameRefresh();
        sys.readSleepTimer().then(function () { if (isOpen && view === "main") refresh(); });
    }

    function close() {
        if (!isOpen) return;
        scanStop();
        root.classList.remove("is-open");
        document.body.classList.remove("has-cc");
        APL.popNav(nav);
        isOpen = false;
    }

    APL.timers.every("cc-refresh", 15000, function () { if (isOpen) refresh(); });   // v1.2.100: shared timer

    APL.controlCenter = {
        open: open, close: close, isOpen: function () { return isOpen; },
        toggle: function () { if (isOpen) close(); else open(); },
        openAirPlay: function () { open(); show("airplay"); },
        openAudio: function () { open(); show("audio"); }
    };
})(window);

/* === js/profiles.js === */
/* ============================================================
   profiles.js — the household's profiles, as on Apple TV.

   Below the time, at the top right: one circle per person (their color,
   their initial), a check mark on the active profile, "+" to add
   someone. Each profile keeps its own Home Screen layout, hidden apps,
   preferences and recent apps (shown here).
   OK: switch profile. Hold OK: avatar, name, color, delete.
   Avatars: your own Memoji (the installer takes them from "Pictures\APL
   Launcher avatars" on the PC), Apple's Memoji (downloaded by
   the installer from wimell/tapback-memojis), then 3D animals in the style
   of Animoji (Microsoft's Fluent Emoji, MIT license — images/avatars/).
   Memoji stay in the screen's package, never in this repository.
   Opens from Control Center (avatar) or Settings.
   ============================================================ */
(function (global) {
    "use strict";

    var APL = global.APL, sys = APL.sys, P = sys.profiles;
    var root, grid, recentTitle, recentRow, nav, isOpen = false;
    // Your Memoji, then Apple's Memoji (local files added by the installer),
    // then the 3D animals. Without Memoji (no network during install): 3D faces.
    var CUSTOM = global.APL_CUSTOM_AVATARS || [];
    var MEMOJI = global.APL_MEMOJI || [];
    var PEOPLE = ["baby-light", "boy-light", "child-medium-dark", "girl-dark", "girl-medium", "man-bald-medium-dark", "man-beard-medium-light", "man-blonde-hair-medium-light", "man-curly-hair-dark", "man-light", "man-medium-light", "man-red-hair-medium-light", "man-white-hair-light", "old-man-medium", "old-woman-medium-light", "person-beard-medium", "person-dark", "woman-blonde-hair-light", "woman-curly-hair-medium-dark", "woman-dark", "woman-medium", "woman-red-hair-light", "woman-white-hair-medium", "woman-with-headscarf-medium"];
    var ANIMALS = ["cat-face", "dog-face", "fox", "panda", "koala", "lion", "tiger-face", "monkey-face", "unicorn", "bear", "hamster", "frog", "alien", "robot", "ghost", "rabbit-face"];
    var AVATARS = CUSTOM.concat(MEMOJI.length ? MEMOJI : PEOPLE, ANIMALS);
    function asset(p) { return global.APL_ASSET ? global.APL_ASSET(p) : p; }
    /* An avatar's image: personal Memoji stay on the screen (never on GitHub) */
    function avatarSrc(k) {
        return k.indexOf("/") > -1 ? "images/avatars/" + k : asset("images/avatars/" + k + ".png");
    }
    /* Pastel color behind an avatar, as on Apple TV */
    function pastel(hex) {
        var h = String(hex || "#0a84ff").replace("#", ""), out = "#";
        for (var i = 0; i < 3; i++) {
            var v = parseInt(h.substr(i * 2, 2), 16);
            out += ("0" + Math.round(v + (255 - v) * 0.55).toString(16)).slice(-2);
        }
        return out;
    }

    function el(tag, cls, html) {
        var e = document.createElement(tag);
        if (cls) e.className = cls;
        if (html !== undefined) e.innerHTML = html;
        return e;
    }
    function initial(name) { return (String(name || "").trim().charAt(0) || "?").toUpperCase(); }

    /* A profile's badge: its color and its initial */
    function paint(node, p) {
        if (p.avatar) {
            node.style.background = pastel(p.color);
            node.innerHTML = '<img class="pavatar' + (p.avatar.indexOf("/") > -1 ? ' pavatar--memoji' : '') + '" alt="" src="' + avatarSrc(p.avatar) + '">';
            return;
        }
        node.style.background = "radial-gradient(circle at 35% 28%, rgba(255,255,255,0.45), rgba(255,255,255,0) 55%), " + p.color;
        node.textContent = initial(p.name);
    }
    function paintStatus() {
        var a = document.querySelector(".status__avatar");
        if (a) { a.classList.add("is-profile"); paint(a, P.current()); }
        // A single profile: nothing to tell apart, the time stays alone (profiles are still in Control Center)
        var s = document.querySelector(".status");
        if (s) s.classList.toggle("is-alone", P.list().length < 2);
    }

    function buildDom() {
        root = el("section", "profiles");
        root.appendChild(el("div", "profiles__dim"));
        var panel = el("div", "profiles__panel");
        grid = el("div", "profiles__grid");
        recentTitle = el("div", "profiles__section");
        recentRow = el("div", "profiles__recents");
        panel.appendChild(grid); panel.appendChild(recentTitle); panel.appendChild(recentRow);
        root.appendChild(panel);
        document.body.appendChild(root);
        nav = new APL.Nav({
            onSelect: function (i, t) { if (t._run) t._run(); },
            onLongPress: function (i, t) { if (t._profile) menu(t._profile, t); },
            onBack: close
        });
    }

    function render(focusId) {
        grid.innerHTML = ""; recentRow.innerHTML = "";
        var tiles = [], cur = P.current(), focus = 0;
        P.list().forEach(function (p) {
            var t = el("div", "pitem" + (p.id === cur.id ? " is-current" : ""));
            var av = el("span", "pitem__avatar");
            paint(av, p);
            t.appendChild(av);
            if (p.id === cur.id) t.appendChild(el("span", "pitem__check", APL.icon("check", 22, 3)));
            var name = el("span", "pitem__name");
            name.textContent = p.name;
            t.appendChild(name);
            t._profile = p;
            t._run = function () { choose(p); };
            if (p.id === (focusId || cur.id)) focus = tiles.length;
            grid.appendChild(t); tiles.push(t);
        });
        var add = el("div", "pitem pitem--add", '<span class="pitem__avatar">' + APL.icon("plus", 52, 2.2) + '</span><span class="pitem__name">' + APL.t("Add") + '</span>');
        add._run = addProfile;
        grid.appendChild(add); tiles.push(add);

        // The profile's history: its latest apps
        var all = APL.allApps ? APL.allApps() : [], byId = {};
        all.forEach(function (a) { byId[a.id] = a; });
        var recent = (sys.pref("recentApps") || []).map(function (id) { return byId[id]; }).filter(Boolean).slice(0, 6);
        recentTitle.textContent = recent.length ? APL.t("Recently Opened · {name}", { name: cur.name }) : "";
        recent.forEach(function (a) {
            var t = el("div", "precent");
            var art = el("span", "precent__art");
            if (a.tile) art.style.background = "#111 center / cover no-repeat url('" + a.tile + "')";
            else if (a.icon) art.innerHTML = '<img alt="" src="' + a.icon + '">';
            else art.textContent = initial(a.name);
            t.appendChild(art);
            t._run = function () { close(); if (APL.launchById) APL.launchById(a.id); };
            recentRow.appendChild(t); tiles.push(t);
        });
        nav.setTiles(tiles);
        nav.focus(focus);
    }

    function choose(p) {
        if (p.id !== P.current().id) {
            P.switchTo(p.id);
            APL.toast(APL.t("Hello, {name}!", { name: p.name }), true);
        }
        close();
    }

    function addProfile() {
        var p = P.add();
        render(p.id);
        rename(p, function () { chooseAvatar(p); });
    }

    /* Choose an avatar: your Memoji, Apple's, then 3D animals */
    function chooseAvatar(p) {
        var box = el("div", "apicker", '<h2 class="apicker__title">' + APL.t("Choose Your Avatar") + '</h2><div class="apicker__scroll"><div class="apicker__grid"></div></div>');
        var g = box.querySelector(".apicker__grid"), tiles = [], at = 0;
        AVATARS.forEach(function (k, i) {
            var t = el("div", "apicker__item");
            t.style.background = pastel(P.colors[i % P.colors.length]);
            t.innerHTML = '<img alt="" src="' + avatarSrc(k) + '">';
            if (k.indexOf("/") > -1) t.classList.add("is-custom");
            t._key = k; t._color = P.colors[i % P.colors.length];
            if (k === p.avatar) at = i;
            g.appendChild(t); tiles.push(t);
        });
        document.body.appendChild(box);
        // The grid scrolls to keep the chosen row on screen (3rd row at the lowest)
        var ROW = 158;
        var pick = new APL.Nav({
            onFocus: function (i, t) {
                g.style.transform = "translateY(" + (-Math.max(0, Math.round(t.offsetTop / ROW) - 2) * ROW) + "px)";
            },
            onSelect: function (i, t) {
                P.update(p.id, { avatar: t._key, color: t._color });
                done();
            },
            onBack: done
        });
        function done() {
            APL.popNav(pick);
            if (box.parentNode) box.parentNode.removeChild(box);
            if (isOpen) render(p.id);
            paintStatus();
        }
        pick.setTiles(tiles);
        pick.focus(at);
        APL.pushNav(pick);
    }

    /* Rename: text field (the screen's keyboard opens) */
    function rename(p, then) {
        var box = el("div", "pprompt", '<div class="pprompt__box"><h2 class="pprompt__title">' + APL.t("Profile Name") + '</h2>' +
            '<input class="pprompt__input" type="text" maxlength="20"><p class="pprompt__hint">' + APL.t("OK to confirm · Back to cancel") + '</p></div>');
        document.body.appendChild(box);
        var input = box.querySelector("input"), done = false;
        input.value = p.name;
        function finish(ok) {
            if (done) return;
            done = true;
            var v = input.value.trim();
            if (ok && v) P.update(p.id, { name: v });
            box.parentNode.removeChild(box);
            if (isOpen) render(p.id);
            paintStatus();
            if (then) then();
        }
        input.addEventListener("keydown", function (e) {
            if (e.keyCode === 13) { e.preventDefault(); e.stopPropagation(); finish(true); }
            else if (e.keyCode === 27 || e.keyCode === 10009) { e.preventDefault(); e.stopPropagation(); finish(false); }
        });
        input.addEventListener("blur", function () { setTimeout(function () { finish(true); }, 0); });
        setTimeout(function () { input.focus(); try { input.select(); } catch (e) {} }, 50);
    }

    function menu(p, t) {
        var items = [
            { label: APL.t("Choose Avatar"), icon: "person", run: function () { chooseAvatar(p); } },
            { label: APL.t("Rename"), icon: "sliders", run: function () { rename(p); } },
            { label: APL.t("Change Color"), icon: "sparkle", run: function () {
                var c = P.colors, k = (c.indexOf(p.color) + 1) % c.length;
                P.update(p.id, { color: c[k] }); render(p.id); paintStatus();
            } },
            { label: p.kid ? APL.t("Child Profile: On") : APL.t("Child Profile: Off"), icon: "person", run: function () {
                P.update(p.id, { kid: !p.kid }); render(p.id); paintStatus();
                APL.toast(!p.kid ? APL.t("Child Profile: On") : APL.t("Child Profile: Off"), true);
            } }
        ];
        if (P.list().length > 1) items.push({ label: APL.t("Delete Profile"), icon: "trash", destructive: true, run: function () {
            APL.alert({
                title: APL.t("Delete “{name}”?", { name: p.name }),
                message: APL.t("Its Home Screen layout, preferences and history will be erased."),
                buttons: [{ label: APL.t("Delete"), destructive: true, run: function () { P.remove(p.id); render(); paintStatus(); } },
                          { label: APL.t("Cancel") }],
                focus: 1
            });
        } });
        APL.contextMenu.open(t.querySelector(".pitem__avatar") || t, items);
    }

    function open() {
        if (P.isKid && P.isKid()) { try { APL.toast(APL.t("Child profile is locked"), true); } catch (e) {} return; }   // v1.99.0
        if (!root) buildDom();
        render();
        root.classList.add("is-open");
        document.body.classList.add("has-profiles");
        APL.pushNav(nav);
        isOpen = true;
    }
    function close() {
        if (!isOpen) return;
        root.classList.remove("is-open");
        document.body.classList.remove("has-profiles");
        APL.popNav(nav);
        isOpen = false;
    }

    P.onChange(paintStatus);
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", paintStatus);
    else paintStatus();

    APL.profilesUI = { open: open, close: close, isOpen: function () { return isOpen; }, paint: paint, chooseAvatar: chooseAvatar };
})(window);

