        if (now < t.fajr) return (A ? "السحور ينتهي بعد " : "Suhoor ends in ") + hm(t.fajr - now);
        if (now < t.maghrib) return (A ? "الإفطار بعد " : "Iftar in ") + hm(t.maghrib - now);
