        chips("النوع", TYPES.map(function (t) { return [t[0], t[2] + " " + APL.enx(t[1])]; }), draft.type, function (v) { draft.type = v; if (draft.isNew) draft.name = ""; paint("type-" + TYPES.map(function (t) { return t[0]; }).indexOf(v)); }, "type-");
